	return (
		<Box as="section" aria-labelledby="my-week-title" padding="space.300" backgroundColor="elevation.surface.raised" xcss={styles.heroCard}>
			<Stack space="space.200">
				<Heading size="small" as="h2" id="my-week-title">
					今週のあなたの相手
				</Heading>
				{body}
			</Stack>
		</Box>
	);
}

