function nextPair(weeks: Week[], from: number, members: Member[], userId: number) {
	for (let i = from; i < weeks.length; i++) {
		const m = myWeek(weeks[i], members, userId);
		if (m.kind === "pair") return { week: weeks[i], partner: m.partner };
	}
	return undefined;
}

